class Solution {
public:
    int beautifulSubsets(vector<int>& nums, int k) {
        map<int, int> cnt;
        for (int x : nums) cnt[x]++;

        unordered_map<int, vector<int>> groups;
        for (auto& [v, c] : cnt) {
            groups[v % k].push_back(v);
        }

        long long result = 1;
        for (auto& [r, vals] : groups) {
            long long prev2 = 1, prev1 = 1;
            for (int i = 0; i < (int)vals.size(); i++) {
                int v = vals[i];
                int c = cnt[v];
                long long pow2c = 1LL << c;
                long long ways = pow2c - 1;
                long long cur;
                if (i == 0 || vals[i] - vals[i - 1] != k) {
                    cur = prev1 * pow2c;
                } else {
                    cur = prev1 + prev2 * ways;
                }
                prev2 = prev1;
                prev1 = cur;
            }
            result *= prev1;
        }

        return (int)(result - 1);
    }
};
